const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
const exp = pkg.exports && pkg.exports["."];
if (!exp || !exp.types) {
  console.error("ERROR: agents root types entry is missing");
  process.exit(2);
}
const file = path.join(root, exp.types);
let text = fs.readFileSync(file, "utf8");
for (const m of text.matchAll(/from "(\.\.?\/[^"]+)\.js"/g)) {
  const dep = path.join(path.dirname(file), m[1] + ".d.ts");
  if (fs.existsSync(dep)) text += "\n" + fs.readFileSync(dep, "utf8");
}
const re = /\/\*\*((?:(?!\*\/)[\s\S])*)\*\/\s*\n\s*subAgent<T extends Agent>\(/;
const m = text.match(re);
if (!m) {
  console.error("ERROR: agents " + pkg.version + " Agent.subAgent declaration with JSDoc not found");
  process.exit(2);
}
const doc = m[1];
if (/@deprecated[^\n]*dynamicAgents\.get\b/.test(doc)) {
  console.log("OK: agents " + pkg.version + " Agent.subAgent is @deprecated in favor of this.dynamicAgents.get");
  process.exit(0);
}
if (!/@deprecated/.test(doc)) {
  console.error("FAIL: agents " + pkg.version + " Agent.subAgent is not marked @deprecated");
  process.exit(1);
}
console.error("ERROR: subAgent is @deprecated but does not point to dynamicAgents.get");
process.exit(2);

